const s = $('Store Settings').first().json;
const m = $('Receive Bot Message').first().json.message || {};
const chat_id = String((m.chat || {}).id || '');
const message_id = String(m.message_id || '');
const reply_to_id = String((m.reply_to_message || {}).message_id || '');
const text = String(m.text || '').trim();
const email = (s.allowed_chats || {})[chat_id] || '';
let command = 'question', topic = '', mode = '7days', number = null;
// list dates -> from/to (YYYY-MM-DD); dig / update -> a story number or search words; save / forget -> how many exchanges.
let from = '', to = '', range_label = '', range_error = '', dig_number = '', dig_query = '', question = '', count = '', end_conversation = false;
const STOP = new Set(['the', 'a', 'an', 'about', 'story', 'that', 'what', 'with', 'of', 'to', 'for', 'did', 'was', 'is', 'and', 'in', 'on', 'made', 'by', 'this', 'it', 'from', 'happened', 'news']);
const wordsOf = (t) => [...new Set(t.toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, ' ').split(/\s+/).filter(w => w.length > 1 && !STOP.has(w)))].join(' or ');
const today = $now.setZone('Europe/Rome').toISODate();
const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const iso = (d) => d.toISOString().slice(0, 10);
const day = (y, mo, d) => new Date(Date.UTC(y, mo - 1, d));
const fmt = (d) => d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()][0].toUpperCase() + MONTHS[d.getUTCMonth()].slice(1) + ' ' + d.getUTCFullYear();
const readPart = (p) => { // "13", "13 October", "October 2026", "September 26", "13 Oct 2026"
  const words = p.toLowerCase().replace(/[,.]/g, ' ').split(/\s+/).filter(Boolean);
  let month = null, d = null, y = null, monthAt = -1;
  words.forEach((w, i) => { const k = MONTHS.findIndex(n => w.length >= 3 && n.startsWith(w)); if (k >= 0 && month === null) { month = k + 1; monthAt = i; } });
  words.forEach((w, i) => { if (!/^\d+$/.test(w)) return; const n = Number(w);
    if (w.length === 4) y = n;
    else if (month !== null && i === monthAt + 1 && w.length === 2 && !words.slice(0, monthAt).some(x => /^\d+$/.test(x))) y = 2000 + n; // "September 26" = September 2026
    else if (n >= 1 && n <= 31 && d === null) d = n; });
  return { month, d, y };
};
const readRange = (t) => {
  const thisYear = Number(today.slice(0, 4));
  const now = day(thisYear, Number(today.slice(5, 7)), Number(today.slice(8, 10)));
  t = t.trim().toLowerCase();
  if (!t) return { a: new Date(now - 6 * 864e5), b: now };
  let mm;
  if ((mm = t.match(/^(?:last|past)\s+(\d+)\s+(day|days|week|weeks)$/))) { const n = Number(mm[1]) * (mm[2].startsWith('week') ? 7 : 1); return { a: new Date(now - (n - 1) * 864e5), b: now }; }
  if (t === 'this week') { const back = (now.getUTCDay() + 6) % 7; return { a: new Date(now - back * 864e5), b: now }; }
  if (t === 'last week') { const back = (now.getUTCDay() + 6) % 7 + 7; const a = new Date(now - back * 864e5); return { a, b: new Date(+a + 6 * 864e5) }; }
  const parts = t.split(/\s*(?:\s-\s|-|–|—|\bto\b|\buntil\b)\s*/).filter(Boolean);
  if (parts.length < 1 || parts.length > 2) return null;
  const p1 = readPart(parts[0]), p2 = parts[1] ? readPart(parts[1]) : null;
  if (!p2) {
    if (p1.month === null) return null;
    const y = p1.y || thisYear;
    if (p1.d === null) return { a: day(y, p1.month, 1), b: day(y, p1.month + 1, 0) };
    return { a: day(y, p1.month, p1.d), b: day(y, p1.month, p1.d) };
  }
  const m2 = p2.month, y2 = p2.y || p1.y || thisYear;
  const m1 = p1.month || m2, y1 = p1.y || (p1.month && m2 && p1.month > m2 ? y2 - 1 : y2);
  if (m1 === null || m2 === null) return null;
  const a = day(y1, m1, p1.d || 1), b = p2.d ? day(y2, m2, p2.d) : day(y2, m2 + 1, 0);
  return { a, b };
};
// The command is the first word, with or without a symbol or digit in front: "#search", "@search", "2search", "/search" and "search" are the same.
const head = text.replace(/^[^\p{L}]+/u, '');
const word = (head.match(/^\p{L}[\p{L}_-]*/u) || [''])[0].toLowerCase();
const rest = head.slice(word.length).replace(/^[\s:,.-]+/, '').trim();
const nWords = text.split(/\s+/).filter(Boolean).length;
const NUM = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
// "last 2", "last two messages" -> 2; "this one only", "just this", "last message" -> 1; nothing -> the whole conversation.
const readCount = (t) => { const x = t.toLowerCase(); const mm = x.match(/\blast\s+(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\b/);
  if (mm) return String(NUM[mm[1]] || Number(mm[1]));
  return /\b(this one|only|just this|this message|that one|last message|last answer|last exchange|last question)\b/.test(x) ? '1' : ''; };
if (/^\d{1,2}$/.test(text)) { command = 'number'; number = Number(text); }
else if (word === 'help' || (word === 'start' && nWords === 1)) command = 'help';
else if (word === 'search') {
  command = 'search'; topic = rest;
  if (/^(today|last day)\b/i.test(topic) || /\b(today|last day)$/i.test(topic)) {
    mode = 'today'; topic = topic.replace(/^(today|last day)\s*/i, '').replace(/\s*(today|last day)$/i, '').trim();
  }
}
else if (word === 'reports') command = 'reports';
else if (word === 'list') {
  const r = readRange(rest);
  // A sentence that starts with "list" but has no dates in it is a question, not the list command.
  if (!r && nWords > 4) command = 'question';
  else {
    command = 'list';
    if (!r || isNaN(r.a) || isNaN(r.b) || r.b < r.a) range_error = 'I could not read those dates. Examples: list, list 13 October - 21 October 2026, list September 2026, list last 2 weeks.';
    else if ((r.b - r.a) / 864e5 + 1 > 31) range_error = 'That is more than a month. Ask for one month at most, e.g. list September 2026.';
    else { from = iso(r.a); to = iso(r.b); range_label = from === to ? fmt(r.a) : fmt(r.a).replace(/ \d{4}$/, r.a.getUTCFullYear() === r.b.getUTCFullYear() ? '' : ' ' + r.a.getUTCFullYear()) + ' to ' + fmt(r.b); }
    if (range_error) { from = '1900-01-01'; to = '1900-01-01'; }
  }
}
else if (word === 'dig') {
  command = 'dig'; topic = rest;
  if (/^#?\d+$/.test(topic)) dig_number = topic.replace('#', ''); else dig_query = wordsOf(topic);
}
else if (word === 'update') {
  // "update 214 did the patient survive?" or "update the AI virus story, did the patient survive?"
  command = 'update'; topic = rest;
  const mm = topic.match(/^#?(\d+)\b\s*(.*)$/);
  if (mm) { dig_number = mm[1]; question = mm[2].trim(); } else { dig_query = wordsOf(topic); question = topic; }
}
else if (word === 'provide-all' || word === 'provide_all' || word === 'provideall' || (word === 'provide' && /^all\b/i.test(rest))) command = 'provide_all';
else if (word === 'provide') command = 'provide';
else if (['save', 'close', 'wrap', 'wrapup', 'wrap-up', 'enough', 'done'].includes(word) && nWords <= 8) {
  command = 'save'; count = readCount(rest); end_conversation = word !== 'save';
}
else if (word === 'forget' && nWords <= 8) { command = 'forget'; count = readCount(rest); }
// Where Route Command sends it: help, search (with a topic), a fixed command ("Bot Commands"), or the conversation ("Story Chat").
const route = command === 'help' ? 'help' : command === 'search' ? (topic ? 'search' : 'command') : ['save', 'forget', 'question'].includes(command) ? 'chat' : 'command';
const fn = command === 'save' ? 'save' : command === 'forget' ? 'forget' : 'ask';
return [{ json: { chat_id, message_id, reply_to_id, email, text, command, route, function: fn, topic, mode, number, from, to, range_label, range_error,
  dig_number, dig_query, question, count, end_conversation, allowed: !!email && !!text } }];

const c = $('Read Command').first().json;
const stamp = $now.setZone('Europe/Rome').toFormat('yyyyLLdd-HHmmss');
return [{ json: { run_id: 'CC-' + stamp + '-' + Math.random().toString(36).slice(2, 6).toUpperCase(), keywords: [c.topic], mode: c.mode,
  recipient: c.email, requested_by: 'telegram', chat_id: c.chat_id, check_duplicates: false } }];

// Markdown-ish text -> Telegram HTML, split between lines into messages under 3,800 characters.
// Escape first; every tag opens and closes on its own line, so a cut never leaves a tag open.
const LIMIT = 3800;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const FLAG = { 'Corroborated': '✅', 'Single source': '🔹', 'Disputed': '⚠️', 'Unverified': '❔', 'Opinion': '💬', 'Not checked': '⏸️' };
const linkify = (s) => esc(s).replace(/(https?:\/\/[^\s<]+)/g, (u) => '<a href="' + u.replace(/"/g, '&quot;') + '">' + u.replace(/^https?:\/\/(www\.)?/, '').slice(0, 60) + '</a>');
const out = [];
const rc = $('Read Command').first().json;
for (const it of $input.all()) {
  // A failed hand-off arrives without text: the user still gets an answer (the sub-workflow has already alerted).
  const chat_id = it.json.chat_id || rc.chat_id;
  const conversation_id = String(it.json.conversation_id || ''), exchange_no = String(it.json.exchange_no ?? '');
  const lines = String(it.json.text || 'Something went wrong on my side. Try again in a minute.').replace(/\r\n?/g, '\n').split('\n').map((l) => {
    let m;
    if ((m = l.match(/^###\s+(.*)$/))) return '<b>' + esc(m[1]) + '</b>';
    if ((m = l.match(/^##\s+(.*)$/))) return '<b>' + esc(m[1].toUpperCase()) + '</b>';
    if ((m = l.match(/^\[(Corroborated|Single source|Disputed|Unverified|Opinion|Not checked)(?::\s*([^\]]+))?\]\s*(.*)$/))) return (FLAG[m[1]] || '▪️') + ' <b>' + esc(m[1]) + (m[2] ? ': ' + esc(m[2]) : '') + '</b> ' + linkify(m[3]);
    if ((m = l.match(/^\s*[-*]\s+(.*)$/))) return '▫️ ' + linkify(m[1]);
    return linkify(l);
  });
  const chunks = []; let cur = [];
  for (const l of lines) {
    if ((cur.join('\n').length + l.length + 1) > LIMIT && cur.length) { chunks.push(cur.join('\n')); cur = []; }
    cur.push(l.length > LIMIT ? l.slice(0, LIMIT - 20) + '…' : l);
  }
  if (cur.length) chunks.push(cur.join('\n'));
  chunks.forEach((c, i) => {
    const html = (chunks.length > 1 ? '<i>(' + (i + 1) + '/' + chunks.length + ')</i>\n' : '') + c.replace(/\n{3,}/g, '\n\n').trim();
    out.push({ json: { chat_id, conversation_id, exchange_no, telegram_text: html, telegram_plain: html.replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&') } });
  });
}
return out;
